import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken(); int n = (int) in.nval;
        in.nextToken(); int k = (int) in.nval;
        in.nextToken(); int c = (int) in.nval;

        long[] pref = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            in.nextToken();
            pref[i] = pref[i - 1] + (long) in.nval;
        }

        final int INF = Integer.MAX_VALUE / 2;

        // dp[j][i] = soma mínima coberta nos i primeiros quadrados usando j etiquetas
        int[] prev = new int[n + 1]; // j = 0: nada coberto
        int[] cur = new int[n + 1];

        for (int j = 1; j <= k; j++) {
            cur[0] = INF;
            for (int i = 1; i <= n; i++) {
                int best;
                // deixa o quadrado i descoberto
                if (cur[i - 1] < INF) best = cur[i - 1];
                else best = INF;
                // coloca uma etiqueta cobrindo [i-c+1, i]
                if (i >= c) {
                    int base = prev[i - c];
                    if (base < INF) {
                        int cand = base + (int) (pref[i] - pref[i - c]);
                        if (cand < best) best = cand;
                    }
                }
                cur[i] = best;
            }
            int[] t = prev; prev = cur; cur = t;
        }

        System.out.println(pref[n] - prev[n]);
    }
}
